//! Synthetic unit tests (`wlib.md` §14, `wstate.md` §15). All fixtures are generated by
//! our own builders; no game data.

use std::sync::Arc;

use tessera_formats::{Did, name_hash};
use tessera_props::MemorySource;

use crate::library::{CHUNK_ATTRIBUTES, CHUNK_PARENTS};
use crate::testkit::*;
use crate::*;

const H_INT: u32 = 0x0000_0011;
const H_REF: u32 = 0x0000_0022;
const H_I64: u32 = 0x0000_0033;

/// Root class 1 (int, ref), child class 2 (int, ref, int64), class 0 undefined.
fn small_library() -> LibraryBuilder {
    LibraryBuilder::new(3)
        .define(1, &[(H_INT, ValueType::Int), (H_REF, ValueType::Reference)])
        .define(
            2,
            &[
                (H_INT, ValueType::Int),
                (H_REF, ValueType::Reference),
                (H_I64, ValueType::Int64),
            ],
        )
        .parent(2, 1)
        .singleton(2)
}

fn malformed_reason(e: &WStateError) -> String {
    e.to_string()
}

#[test]
fn minimal_library_parses() {
    let mut b = small_library();
    b.extra_chunks.push((1, vec![0, 0, 0, 0]));
    b.extra_chunks.push((2, vec![0, 0, 0, 0, 0, 0, 0, 0]));
    b.extra_chunks.push((999, vec![1, 2, 3]));
    let lib = ClassLibrary::parse(&b.build()).expect("parse");
    assert_eq!(lib.version, 38);
    assert_eq!(lib.header_extra.len(), 1);
    assert_eq!(lib.len(), 3);
    assert_eq!(lib.defined_count(), 2);
    assert_eq!(lib.listed_count(), 2);
    assert_eq!(lib.attribute_count(), 5);
    assert!(lib.class(0).is_none());
    assert!(!lib.is_defined(0));
    assert!(lib.class(7).is_none());
    let c2 = lib.class(2).expect("class 2");
    assert_eq!(c2.slot_count(), 4);
    assert_eq!(c2.instance_size, 32);
    assert_eq!(c2.ref_slots, vec![1]);
    assert_eq!(
        c2.attribute(H_I64).map(|a| (a.slot, a.ty)),
        Some((2, ValueType::Int64))
    );
    assert_eq!(c2.serialized_size(), 16);
    assert_eq!(c2.reference_attributes().count(), 1);
    assert_eq!(lib.parent(2), Some(1));
    assert_eq!(lib.parent(1), None);
    assert_eq!(lib.ancestors(2).collect::<Vec<_>>(), vec![1]);
    assert_eq!(lib.depth(2), 1);
    assert!(lib.is_a(2, 1));
    assert!(lib.is_a(2, 2));
    assert!(!lib.is_a(1, 2));
    assert_eq!(lib.singletons(), &[2]);
    assert_eq!(lib.singleton_did(2), Some(Did(0x7600_0002)));
    assert_eq!(lib.singleton_did(1), None);
    assert_eq!(lib.bytecode_len, Some(0));
    assert_eq!(lib.message_count, Some(0));
    assert!(lib.warnings().is_empty(), "{:?}", lib.warnings());
    assert_eq!(lib.classes().count(), 2);
}

#[test]
fn attribute_list_order_is_serialization_order() {
    // Hashes 12 and 1 with hint 0 (11 buckets): 12 % 11 = 1, 1 % 11 = 1, so stored order
    // is slot order; 22 % 11 = 0 goes first.
    let lib = ClassLibrary::parse(
        &LibraryBuilder::new(2)
            .define(
                1,
                &[
                    (12, ValueType::Int),
                    (1, ValueType::Float),
                    (22, ValueType::Int),
                ],
            )
            .build(),
    )
    .expect("parse");
    let hashes: Vec<u32> = lib.attributes(1).iter().map(|a| a.hash).collect();
    assert_eq!(hashes, vec![22, 12, 1]);
    assert_eq!(lib.attributes(0), &[]);
}

#[test]
fn library_versions() {
    for v in [30, 36, 38] {
        let mut b = small_library();
        b.version = v;
        let lib = ClassLibrary::parse(&b.build()).unwrap_or_else(|e| panic!("v{v}: {e}"));
        assert_eq!(lib.version, v);
    }
    let mut b = small_library();
    b.version = 16;
    assert!(matches!(
        ClassLibrary::parse(&b.build()),
        Err(WStateError::UnsupportedVersion { version: 16 })
    ));
}

#[test]
fn library_wrong_marker() {
    let mut bytes = small_library().build();
    bytes[16] ^= 0xFF; // first chunk marker (after 16 header bytes at version 38)
    let e = ClassLibrary::parse(&bytes).unwrap_err();
    assert!(malformed_reason(&e).contains("marker"), "{e}");
}

#[test]
fn library_stop_byte_must_be_one() {
    let mut b = small_library();
    b.stop_byte = 2;
    assert!(ClassLibrary::parse(&b.build()).is_err());
    let mut bytes = small_library().build();
    bytes.push(0);
    assert!(matches!(
        ClassLibrary::parse(&bytes),
        Err(WStateError::TrailingBytes { .. })
    ));
}

#[test]
fn library_huge_class_count_fails_without_allocating() {
    let b = small_library();
    let mut chunks = b.chunks();
    chunks[0].1 = vec![0xDF, 0xFF, 0xFF, 0xFF]; // VLE ~ 0x1FFFFFFF entries, 4 bytes of data
    let e = ClassLibrary::parse(&assemble_library(38, &chunks, 1)).unwrap_err();
    assert!(matches!(e, WStateError::Format { .. }), "{e}");
}

#[test]
fn library_class_index_mismatch() {
    let mut b = small_library();
    if let Some(Some(c)) = b.classes.get_mut(1) {
        c.stored_index = Some(5);
    }
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("L2"), "{e}");
}

#[test]
fn library_attribute_list_for_undefined_class() {
    let b = small_library();
    let other = LibraryBuilder::new(3).define(0, &[(H_INT, ValueType::Int)]);
    let mut chunks = b.chunks();
    for (t, p) in &mut chunks {
        if *t == CHUNK_ATTRIBUTES {
            *p = other.attribute_lists();
        }
    }
    let e = ClassLibrary::parse(&assemble_library(38, &chunks, 1)).unwrap_err();
    assert!(e.to_string().contains("undefined class"), "{e}");
}

#[test]
fn library_attribute_type_disagrees_with_slot() {
    let mut b = small_library();
    if let Some(Some(c)) = b.classes.get_mut(1) {
        c.slots[0].1 = 3;
    }
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("L6"), "{e}");
}

#[test]
fn library_64bit_second_slot_type() {
    let mut b = small_library();
    if let Some(Some(c)) = b.classes.get_mut(2) {
        c.slots[3].1 = 2;
    }
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("L6"), "{e}");
}

#[test]
fn library_uncovered_slot_and_duplicate_hash() {
    let mut b = small_library();
    if let Some(Some(c)) = b.classes.get_mut(1) {
        c.slots.push((0, 2));
    }
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("not covered"), "{e}");

    let mut b = small_library();
    if let Some(Some(c)) = b.classes.get_mut(1) {
        c.attributes[1].0 = c.attributes[0].0;
    }
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("twice"), "{e}");
}

#[test]
fn library_parent_cycle_and_range() {
    let b = small_library().parent(1, 2);
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("cycle"), "{e}");
    let b = small_library().parent(1, 9);
    assert!(ClassLibrary::parse(&b.build()).is_err());
    let b = small_library().parent(1, 1);
    assert!(ClassLibrary::parse(&b.build()).is_err());
    let mut b = small_library();
    b.parents.push(NO_PARENT_U32);
    let e = ClassLibrary::parse(&b.build()).unwrap_err();
    assert!(e.to_string().contains("L7"), "{e}");
}

const NO_PARENT_U32: u32 = crate::library::NO_PARENT;

#[test]
fn library_missing_chunk() {
    let chunks: Vec<_> = small_library()
        .chunks()
        .into_iter()
        .filter(|(t, _)| *t != CHUNK_PARENTS)
        .collect();
    assert!(matches!(
        ClassLibrary::parse(&assemble_library(38, &chunks, 1)),
        Err(WStateError::MissingChunk { chunk_type: 1024 })
    ));
}

#[test]
fn library_cross_check_warnings() {
    // Child lists only its own attribute: L8 violation (warning).
    let b = LibraryBuilder::new(3)
        .define(1, &[(H_INT, ValueType::Int)])
        .define(2, &[(H_INT, ValueType::Float)])
        .parent(2, 1)
        .singleton(0);
    let lib = ClassLibrary::parse(&b.build()).expect("parse");
    assert!(lib.warnings().contains(&LibraryWarning::NotFlattened {
        class: 2,
        ancestor: 1
    }));
    assert!(
        lib.warnings()
            .contains(&LibraryWarning::UndefinedSingleton { class: 0 })
    );
}

#[test]
fn library_never_panics_on_truncation() {
    let bytes = small_library().build();
    for n in 0..bytes.len() {
        assert!(ClassLibrary::parse(&bytes[..n]).is_err(), "prefix {n}");
    }
}

// --- object state -------------------------------------------------------------------

/// The worked example of `wstate.md` §15.1, byte for byte.
const WORKED_EXAMPLE: [u8; 60] = [
    0xBC, 0x0A, 0x00, 0x70, // DID
    0x23, 0x01, 0x00, 0x00, // root class
    0x02, 0x00, // imports
    0x00, 0x00, 0x01, // reserved
    0x29, 0x00, 0x00, 0x00, // bundle size 41
    0x02, // item count
    0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, // labels
    0x01, 0x00, // class count
    0x23, 0x01, 0x01, 0x00, 0xF0, 0xDE, 0xBC, 0x0A, 0x01, // class table entry
    0x00, 0x00, 0x00, 0x00, 0x23, 0x01, 0x01, 0x00, 0x00, 0x00, // item 0
    0x00, 0x00, 0x00, 0x00, 0xE1, 0x00, 0x02, 0x48, 0x00, 0x69, 0x00, // item 1
    0x00, // has_links
    0x00, // has_available
];

const EX_CLASS: u16 = 0x0123;
const EX_ATTR: u32 = 0x0ABC_DEF0;

fn example_library() -> ClassLibrary {
    ClassLibrary::parse(
        &LibraryBuilder::new(0x200)
            .define(usize::from(EX_CLASS), &[(EX_ATTR, ValueType::Reference)])
            .build(),
    )
    .expect("library")
}

fn example_builder() -> RecordBuilder {
    RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS))
        .class(EX_CLASS, &[(EX_ATTR, ValueType::Reference)])
        .script(0, EX_CLASS, &[Value::Ref(Ref(1))])
        .object(1, 225, &{
            let mut b = Vec::new();
            put_utf16(&mut b, "Hi");
            b
        })
}

#[test]
fn worked_example_decodes() {
    assert_eq!(example_builder().build(), WORKED_EXAMPLE.to_vec());
    let lib = example_library();
    for ctx in [
        DecodeContext::new(&lib, &tessera_formats::NoSchema),
        DecodeContext::bare(),
    ] {
        let s = ObjectState::parse(&WORKED_EXAMPLE, Did(0x7000_0ABC), ctx).expect("decode");
        assert!(s.is_complete());
        assert!(s.warnings.is_empty(), "{:?}", s.warnings);
        assert_eq!(s.root_class, 0x123);
        assert_eq!(s.item_count(), 2);
        let root = s.root_object().expect("root");
        assert_eq!(root.class(), 0x123);
        assert_eq!(root.len(), 1);
        let target = root
            .follow(EX_ATTR)
            .and_then(Resolved::item)
            .expect("resolves");
        assert_eq!(
            target
                .as_native()
                .and_then(Native::as_string)
                .map(ToString::to_string),
            Some("Hi".into())
        );
        assert_eq!(target.label(), 1);
        assert_eq!(s.reachable(0), vec![0, 1]);
        assert_eq!(s.reference_counts(), vec![0, 1]);
    }
    assert!(matches!(
        ObjectState::parse(&WORKED_EXAMPLE, Did(0x7000_0ABD), DecodeContext::bare()),
        Err(WStateError::DidMismatch { .. })
    ));
    let h = ObjectHeader::parse(&WORKED_EXAMPLE).expect("header");
    assert_eq!((h.did, h.root_class), (Did(0x7000_0ABC), 0x123));
}

#[test]
fn worked_example_null_reference() {
    let b = RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS))
        .class(EX_CLASS, &[(EX_ATTR, ValueType::Reference)])
        .script(0, EX_CLASS, &[Value::Ref(Ref::NULL)])
        .object(1, 225, &[0]);
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("decode");
    assert!(matches!(
        s.root_object().and_then(|r| r.follow(EX_ATTR)),
        Some(Resolved::Null)
    ));
    assert_eq!(s.reachable(0), vec![0]);
    assert_eq!(s.reference_counts(), vec![0, 0]);
}

#[test]
fn worked_example_never_panics_on_truncation() {
    let lib = example_library();
    for n in 0..WORKED_EXAMPLE.len() {
        assert!(
            ObjectState::parse(
                &WORKED_EXAMPLE[..n],
                Did(0x7000_0ABC),
                DecodeContext::new(&lib, &tessera_formats::NoSchema)
            )
            .is_err(),
            "prefix {n}"
        );
    }
}

/// Decodes `body` as native class `class` (item 1, referenced by the root).
fn native(class: u16, body: &[u8]) -> Native {
    let b = example_builder();
    let b = RecordBuilder {
        items: vec![b.items[0].clone()],
        ..b
    }
    .object(1, class, body);
    let s = ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare())
        .unwrap_or_else(|e| panic!("class {class}: {e}"));
    assert!(s.is_complete(), "class {class}");
    s.item(1)
        .and_then(|i| i.as_native())
        .cloned()
        .expect("native")
}

fn le(words: &[u32]) -> Vec<u8> {
    words.iter().flat_map(|w| w.to_le_bytes()).collect()
}

#[test]
fn codec_maps() {
    for class in [11u16, 13, 35, 37] {
        for n in [0u32, 1, 3] {
            let mut body = Vec::new();
            put_tsize(&mut body, 0, n);
            for k in 0..n {
                // Values 0 (label 0, the root) or null.
                body.extend(le(&[k, if k == 1 { 0xFFFF_FFFF } else { 0 }]));
            }
            let nat = native(class, &body);
            let refs: Vec<Ref> = nat.references().collect();
            match class {
                11 | 13 => {
                    assert_eq!(nat.as_map_u32().map(<[_]>::len), Some(n as usize));
                    assert!(refs.is_empty());
                }
                _ => {
                    assert_eq!(nat.as_ref_map().map(<[_]>::len), Some(n as usize));
                    assert_eq!(refs.len(), n as usize);
                    if n == 3 {
                        assert!(refs[1].is_null());
                    }
                }
            }
        }
    }
    let mut body = Vec::new();
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[7, 1, 2]));
    assert_eq!(
        native(23, &body),
        Native::MapU32U64(
            tessera_formats::TSize { hint: 0, count: 1 },
            vec![(7, 0x2_0000_0001)]
        )
    );
    assert!(matches!(native(97, &body), Native::MapU64U32(_, v) if v == vec![(0x1_0000_0007, 2)]));
    let mut body = Vec::new();
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[7, 1, 0]));
    assert!(
        matches!(native(117, &body), Native::RefMapU64(_, v) if v == vec![(0x1_0000_0007, Ref(0))])
    );
    // 138 and 131: (u32, u32, bool8, u32).
    let mut body = Vec::new();
    put_tsize(&mut body, 0, 2);
    for _ in 0..2 {
        body.extend(le(&[0, 5]));
        body.push(0);
        body.extend(le(&[0xFFFF_FFFF]));
    }
    let n = native(138, &body);
    assert_eq!(n.references().count(), 4);
    let n = native(131, &body);
    assert_eq!(n.references().count(), 0);
}

#[test]
fn codec_arrays_and_sets() {
    for class in [17u16, 25, 176, 182] {
        for n in [0u32, 1, 4] {
            let mut body = le(&[n]);
            for k in 0..n {
                body.extend(le(&[if k == 2 { 0xFFFF_FFFF } else { 0 }]));
            }
            let nat = native(class, &body);
            let r = nat.references().count();
            if class >= 176 {
                assert_eq!(r, n as usize);
            } else {
                assert_eq!(nat.as_array_u32().map(<[_]>::len), Some(n as usize));
                assert_eq!(r, 0);
            }
        }
    }
    for class in [104u16, 111] {
        let mut body = le(&[2]);
        body.extend(le(&[1, 0, 2, 0]));
        assert_eq!(native(class, &body), Native::ArrayU64(vec![1, 2]));
    }
    // Small sets: u16 count, 0, hint, elements in bucket order for hint 0.
    for n in [0u16, 1, 3] {
        let mut body = n.to_le_bytes().to_vec();
        body.extend([0, 0]);
        for k in 0..u32::from(n) {
            body.extend(le(&[k]));
        }
        assert!(matches!(native(18, &body), Native::SetU32(_, v) if v.len() == usize::from(n)));
    }
    let mut body = 1u16.to_le_bytes().to_vec();
    body.extend([0, 1]);
    body.extend(le(&[3, 4]));
    assert!(
        matches!(native(105, &body), Native::SetU64(h, v) if h.hint == 1 && v == vec![0x4_0000_0003])
    );
    let mut body = 1u16.to_le_bytes().to_vec();
    body.extend([0, 0]);
    body.extend(le(&[3, 4]));
    body.push(0);
    assert!(matches!(native(134, &body), Native::SetTriple(_, v) if v == vec![(3, 4, 0)]));

    assert!(
        matches!(native(101, &le(&[1, 5, 6, 2])), Native::MultiMapU64U32(v) if v == vec![(0x6_0000_0005, 2)])
    );
}

#[test]
fn codec_scalars_and_text() {
    // Bitset: 10 bits.
    let n = native(57, &[10, 0xFF, 0x03]);
    assert!(matches!(n, Native::Bitset { bits: 10, ref bytes } if bytes == &[0xFF, 0x03]));
    // Position for each flag bit combination we produce.
    for (flags, extra) in [
        (0x01u8, vec![2u8]),
        (0x02, vec![1, 2]),
        (0x04, vec![1, 0]),
        (0x08, vec![5, 0]),
        (
            0x10,
            [1f32, 2.0, 3.0]
                .iter()
                .flat_map(|f| f.to_le_bytes())
                .collect(),
        ),
        (
            0x20,
            [1f32, 0.0, 0.0, 0.0]
                .iter()
                .flat_map(|f| f.to_le_bytes())
                .collect(),
        ),
        (0x40, vec![]),
        (0x80, vec![]),
    ] {
        let mut body = vec![flags];
        body.extend(extra);
        for class in [160u16, 161] {
            let n = native(class, &body);
            assert_eq!(n.as_position().map(|p| p.flags()), Some(flags));
        }
    }
    let mut body = Vec::new();
    put_position(&mut body, 3, (10, 20), 0, [1.0, 2.0, 3.0]);
    let p = *native(160, &body).as_position().expect("position");
    assert_eq!(p.region(), Some(3));
    assert_eq!(p.landblock(), Some((10, 20)));
    assert_eq!(p.cell(), Some(0));
    // Weighted table.
    let n = native(175, &le(&[1, 7, 8, 9, 0]));
    assert!(matches!(n, Native::WeightedTable(v, 0) if v.len() == 1 && v[0].weight == 8));
    // StringInfo and string.
    let mut body = Vec::new();
    put_string_info_ref(&mut body, 5, 0x2500_0001);
    assert!(native(199, &body).as_string_info().is_some());
    let mut body = Vec::new();
    put_string_info_literal(&mut body, "x");
    assert!(native(199, &body).as_string_info().is_some());
    assert_eq!(native(225, &[0]).as_string().map(|s| s.len()), Some(0));
    // Fixed-size bodies.
    let f: Vec<u8> = (0..7).flat_map(|i| (i as f32).to_le_bytes()).collect();
    assert!(matches!(native(72, &f), Native::Frame(v) if v[6] == 6.0));
    let mut s = vec![1u8];
    s.extend([7u8; 16]);
    s.extend([0u8; 12]);
    s.extend(5f32.to_le_bytes());
    assert!(matches!(native(192, &s), Native::Sphere(b) if b.radius == 5.0 && b.flag == 1));
    let mut barter = le(&[0x7000_0ABC, 0x7000_0001, 1]);
    barter.push(0);
    barter.extend(le(&[0, 0, 0x7000_0002, 3, 0, 0, 0, 0, 0]));
    assert_eq!(barter.len(), 49);
    assert!(
        matches!(native(1942, &barter), Native::BarterEntry(b) if b.pairs[0] == (Did(0x7000_0002), 3))
    );
    assert_eq!(
        native(1980, &[1, 0, 1, 0, 1, 0]),
        Native::Opaque6([1, 0, 1, 0, 1, 0])
    );
    assert_eq!(native(3461, &le(&[1, 2, 3])), Native::TripleU32([1, 2, 3]));
    assert_eq!(native(3740, &le(&[9])), Native::U32(9));
    let n = native(407, &le(&[8, 0, 0]));
    assert!(matches!(n, Native::CompressedBitset(v) if v.len() == 8));
    let mut body = Vec::new();
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[4]));
    put_utf16(&mut body, "v");
    body.extend(le(&[10, 1]));
    assert!(matches!(
        native(3103, &body),
        Native::Vault {
            capacity: 10,
            used: 1,
            ..
        }
    ));
}

#[test]
fn codec_scene_options_and_quest_targets() {
    // Scene info with one entry.
    let mut body = Vec::new();
    put_string_info_ref(&mut body, 1, 0x2500_0001);
    body.extend(le(&[0x7000_0ABC, 1, SCENE_SENTINEL, 1]));
    body.extend([0f32, 1.0].iter().flat_map(|f| f.to_le_bytes()));
    body.extend(le(&[2]));
    put_string_info_ref(&mut body, 2, 0x2500_0001);
    body.extend(le(&[3, 4]));
    body.push(0);
    assert!(
        matches!(native(427, &body), Native::SceneInfo(s) if s.entries.len() == 1 && s.owner == Did(0x7000_0ABC))
    );
    // A bad sentinel fails the record.
    let mut bad = body.clone();
    let at = bad.len() - (4 * 7 + 13 + 1);
    bad[at] ^= 1;
    let b = RecordBuilder {
        items: vec![example_builder().items[0].clone()],
        ..example_builder()
    }
    .object(1, 427, &bad);
    assert!(ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).is_err());

    // Options profile, observed form: 2 sets of 1 kind-0 slot, t1 = 1, t2 = 2, 24 bytes.
    let mut body = le(&[320, 0, 2, 1, 0, 1, 0]);
    body.extend([1, 2]);
    body.extend([0u8; 24]);
    assert!(
        matches!(native(415, &body), Native::OptionsProfile(p) if p.sets.len() == 2 && matches!(p.tail, native::OptionsTail::Fixed(_)))
    );
    // Reported form: t1 = 0, t2 = 1 group with one element.
    let mut body = le(&[320, 0, 0]);
    body.extend([0, 1]);
    body.extend(le(&[9]));
    body.extend([0, 1]);
    body.extend(le(&[1]));
    body.extend([0u8; 16]);
    body.push(0);
    body.extend([0, 0]);
    body.extend([0u8; 24]);
    assert!(
        matches!(native(415, &body), Native::OptionsProfile(p) if matches!(&p.tail, native::OptionsTail::Groups { groups, .. } if groups.len() == 1))
    );

    // Quest targets: one location, seven empty tables, one layered location, one quest.
    let mut body = Vec::new();
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[0x7000_0001, 1]));
    put_position(&mut body, 1, (1, 1), 0, [0.0; 3]);
    body.extend(le(&[5]));
    body.push(0);
    body.extend(le(&[7]));
    for _ in 0..7 {
        put_tsize(&mut body, 0, 0);
    }
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[0x7000_0002, 1]));
    put_position(&mut body, 1, (1, 1), 0, [0.0; 3]);
    body.extend(le(&[5]));
    body.push(0);
    body.extend(le(&[1, 42]));
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[0x7000_0003]));
    put_tsize(&mut body, 0, 1);
    body.extend(le(&[1, 1, 1, 0x7000_0004]));
    put_position(&mut body, 1, (1, 1), 0, [0.0; 3]);
    body.extend(2f32.to_le_bytes());
    body.extend([1, b'a']);
    body.extend(le(&[1]));
    body.push(0x03);
    body.extend(le(&[10, 11]));
    body.push(0);
    let n = native(2479, &body);
    let Native::QuestTargets(q) = n else {
        panic!("quest targets");
    };
    assert_eq!(q.locations.len(), 1);
    assert_eq!(q.tables.len(), 7);
    assert_eq!(q.layered[0].1[0].layers, vec![42]);
    assert_eq!(q.quests[0].1[0].1[0][0].filters, vec![(3, vec![10, 11])]);
}

const SCENE_SENTINEL: u32 = native::SCENE_ENTRY_SENTINEL;

#[test]
fn codec_property_natives_use_schema() {
    let schema: std::collections::BTreeMap<u32, tessera_formats::PropertyType> =
        [(0x100, tessera_formats::PropertyType::Int)]
            .into_iter()
            .collect();
    // 39: PID then value, no echo.
    let mut b = RecordBuilder {
        items: vec![example_builder().items[0].clone()],
        ..example_builder()
    }
    .object(1, 39, &le(&[0x100, 7]));
    let s = ObjectState::parse(
        &b.build(),
        Did(0x7000_0ABC),
        DecodeContext {
            library: None,
            schema: &schema,
        },
    )
    .expect("decode");
    assert!(
        matches!(s.item(1).and_then(|i| i.as_native()), Some(Native::Property(Some(p))) if p.pid == 0x100)
    );
    // Unknown PID fails.
    b.items[1] = {
        let mut it = vec![0, 0, 0, 0];
        it.extend(39u16.to_le_bytes());
        it.extend(le(&[0x200, 7]));
        (1, it)
    };
    assert!(
        ObjectState::parse(
            &b.build(),
            Did(0x7000_0ABC),
            DecodeContext {
                library: None,
                schema: &schema
            }
        )
        .is_err()
    );
    // 166: embedded property set.
    let b = RecordBuilder {
        items: vec![example_builder().items[0].clone()],
        ..example_builder()
    }
    .object(1, 166, &embedded_property_set(&[(0x100, le(&[9]))]));
    let s = ObjectState::parse(
        &b.build(),
        Did(0x7000_0ABC),
        DecodeContext {
            library: None,
            schema: &schema,
        },
    )
    .expect("decode");
    assert_eq!(
        s.item(1)
            .and_then(|i| i.as_native())
            .and_then(Native::as_property_set)
            .map(|p| p.len()),
        Some(1)
    );
    // Null 39 entry.
    let b = RecordBuilder {
        items: vec![example_builder().items[0].clone()],
        ..example_builder()
    }
    .object(1, 39, &le(&[0]));
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("decode");
    assert!(matches!(
        s.item(1).and_then(|i| i.as_native()),
        Some(Native::Property(None))
    ));
}

#[test]
fn did_items_imports_cycles_and_extra_classes() {
    let b = RecordBuilder::new(0x7000_0001, 5)
        .import(0x45, 0x7000_0002, 16)
        .import(0x4E, 0x2000_0001, 0)
        .class(5, &[(H_REF, ValueType::Reference), (H_INT, ValueType::Int)])
        .class(6, &[])
        .script(0, 5, &[Value::Ref(Ref(0)), Value::Int(3)])
        .did_item(1, 0x7000_0002);
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0001), DecodeContext::bare()).expect("decode");
    assert_eq!(s.imports.len(), 2);
    assert_eq!(s.imports[0].flags, Import::FLAG_DID_ITEM);
    assert_eq!(s.did_items().collect::<Vec<_>>(), vec![Did(0x7000_0002)]);
    let root = s.root_object().expect("root");
    assert_eq!(root.int(H_INT), Some(3));
    // The root references itself: resolution is lazy, reachability terminates.
    assert_eq!(
        root.follow(H_REF)
            .and_then(Resolved::item)
            .map(|i| i.index()),
        Some(0)
    );
    assert_eq!(s.reachable(0), vec![0]);
    assert_eq!(s.reference_counts(), vec![1, 0]);
    assert_eq!(s.bundle.classes().len(), 2);
    assert_eq!(s.item(1).and_then(|i| i.as_did()), Some(Did(0x7000_0002)));
}

#[test]
fn typed_access_and_named_attributes() {
    let h = name_hash(b"speed");
    let b = RecordBuilder::new(0x7000_0001, 5)
        .class(
            5,
            &[
                (h, ValueType::Float),
                (H_I64, ValueType::Int64),
                (H_INT, ValueType::Double),
                (H_REF, ValueType::DoubleSigned),
            ],
        )
        .script(
            0,
            5,
            &[
                Value::Float(1.5),
                Value::Int64(1 << 40),
                Value::Double(-1.0),
                Value::Double(2.0),
            ],
        );
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0001), DecodeContext::bare()).expect("decode");
    let root = s.root_object().expect("root");
    assert_eq!(root.get_named("speed"), Some(Value::Float(1.5)));
    assert_eq!(root.float(h), Some(1.5));
    assert_eq!(root.int64(H_I64), Some(1 << 40));
    assert_eq!(root.double(H_INT), Some(-1.0));
    assert_eq!(root.double(H_REF), Some(2.0));
    assert_eq!(root.int(h), None);
    assert!(root.follow(h).is_none());
    assert_eq!(root.attributes().count(), 4);
    assert_eq!(root.reference_attributes().count(), 0);
}

