#[test]
fn unknown_native_class_gives_partial_result() {
    let b = example_builder()
        .object(2, 3053, &[1, 1, 2, 0, 0, 0])
        .object(3, 225, &[0]);
    let mut b = b;
    b.links = Some({
        let mut l = le(&[1]);
        l.push(0);
        l.extend(le(&[13, 99, 0]));
        put_tsize(&mut l, 0, 0);
        l.push(0);
        l
    });
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("partial");
    assert_eq!(
        s.partial,
        Some(Partial {
            class: 3053,
            item: 2,
            item_count: 4
        })
    );
    assert!(!s.is_complete());
    assert_eq!(s.items().len(), 2);
    assert_eq!(s.links.as_ref().map(Vec::len), Some(1));
    // A reference to the undecoded item resolves to "undecoded".
    assert!(matches!(
        s.resolve(Ref(3)),
        Resolved::Undecoded { index: 3 }
    ));
}

#[test]
fn dangling_reference_and_duplicate_label() {
    let b = RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS))
        .class(EX_CLASS, &[(EX_ATTR, ValueType::Reference)])
        .script(0, EX_CLASS, &[Value::Ref(Ref(7))]);
    assert!(matches!(
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()),
        Err(WStateError::DanglingReference { label: 7, item: 0 })
    ));
    let mut b = example_builder();
    b.items[1].0 = 0;
    let e = ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).unwrap_err();
    assert!(e.to_string().contains("twice"), "{e}");
}

#[test]
fn non_contiguous_labels() {
    let b = RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS))
        .class(EX_CLASS, &[(EX_ATTR, ValueType::Reference)])
        .script(0, EX_CLASS, &[Value::Ref(Ref(9))])
        .object(9, 225, &[0])
        .object(5, 225, &[0]);
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("decode");
    assert_eq!(s.item_by_label(9).map(|i| i.index()), Some(1));
    assert_eq!(s.item_by_label(5).map(|i| i.index()), Some(2));
    assert!(s.item_by_label(1).is_none());
    assert!(matches!(s.resolve(Ref(1)), Resolved::Dangling { label: 1 }));
    assert_eq!(s.reachable(0), vec![0, 1]);
}

#[test]
fn hostile_counts_and_trailing_bytes() {
    // Item count far larger than the bundle.
    let mut bytes = example_builder().build();
    bytes[17] = 0xDF; // bundle item count VLE: 4-byte form
    assert!(ObjectState::parse(&bytes, Did(0x7000_0ABC), DecodeContext::bare()).is_err());
    // Import count far larger than the record.
    let mut bytes = example_builder().build();
    bytes[9] = 0x7F;
    assert!(ObjectState::parse(&bytes, Did(0x7000_0ABC), DecodeContext::bare()).is_err());
    // Trailing bytes inside the bundle.
    let mut b = example_builder();
    b.bundle_tail = vec![0];
    assert!(matches!(
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()),
        Err(WStateError::TrailingBytes { what: "bundle", .. })
    ));
    // Trailing bytes after the available-property section.
    let mut b = example_builder();
    b.available = Some(vec![1, 2]);
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("decode");
    assert_eq!(s.available.map(|a| a.pids), Some(vec![1, 2]));
    b.record_tail = vec![0];
    assert!(matches!(
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()),
        Err(WStateError::TrailingBytes {
            what: "object-state record",
            ..
        })
    ));
    // Empty bundle: an object with a class but no state.
    let b = RecordBuilder::new(0x7000_0ABC, 5);
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("decode");
    assert_eq!(s.item_count(), 0);
    assert!(s.root().is_none());
}

#[test]
fn library_mismatch_warns_and_decodes_by_table() {
    let lib = example_library();
    // The record's table says the attribute is an int; the library says reference.
    let b = RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS))
        .class(EX_CLASS, &[(EX_ATTR, ValueType::Int)])
        .script(0, EX_CLASS, &[Value::Int(77)]);
    let s = ObjectState::parse(
        &b.build(),
        Did(0x7000_0ABC),
        DecodeContext::new(&lib, &tessera_formats::NoSchema),
    )
    .expect("decode");
    assert!(
        s.warnings
            .contains(&StateWarning::LibraryMismatch { class: 0x123 })
    );
    assert_eq!(s.root_object().and_then(|r| r.int(EX_ATTR)), Some(77));
    // A script class missing from the table is decoded with the library list.
    let b = RecordBuilder::new(0x7000_0ABC, u32::from(EX_CLASS)).script(
        0,
        EX_CLASS,
        &[Value::Ref(Ref::NULL)],
    );
    let s = ObjectState::parse(
        &b.build(),
        Did(0x7000_0ABC),
        DecodeContext::new(&lib, &tessera_formats::NoSchema),
    )
    .expect("decode");
    assert!(
        s.warnings
            .contains(&StateWarning::ClassNotInTable { class: 0x123 })
    );
    assert!(matches!(
        s.root_object().and_then(|r| r.follow(EX_ATTR)),
        Some(Resolved::Null)
    ));
    // Without a library the same record cannot decode (0x123 has no native codec).
    let s =
        ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).expect("partial");
    assert!(s.partial.is_some());
    assert!(s.warnings.contains(&StateWarning::RootMismatch));
}

// --- store and geography --------------------------------------------------------------

const P_AREA_NAME: u32 = 0x1000_0001;
const P_AREA_TERRITORY: u32 = 0x1000_0002;
const P_AREA_REGION: u32 = 0x1000_0003;
const P_AREA_REGION_ID: u32 = 0x1000_0004;
const P_DUNGEON_NAME: u32 = 0x1000_0005;
const P_DUNGEON_MAP: u32 = 0x1000_0006;
const P_DUNGEON_PARENT: u32 = 0x1000_0007;
const P_REGION_LIST: u32 = 0x1000_0008;
const P_REGION_ENTRY: u32 = 0x1000_0009;
const P_REGION_ID: u32 = 0x1000_000A;
const P_REGION_NAME: u32 = 0x1000_000B;

const AREA: u32 = 0x7000_0010;
const TERRITORY: u32 = 0x7000_0011;
const REGION: u32 = 0x7000_0012;
const DUNGEON: u32 = 0x7000_0020;
const SUB_DUNGEON: u32 = 0x7000_0021;
const CONTROL: u32 = 0x7000_0030;
const OTHER: u32 = 0x7000_0040;

fn si(text: &str) -> Vec<u8> {
    let mut b = Vec::new();
    put_string_info_literal(&mut b, text);
    b
}

fn synthetic_world() -> MemorySource {
    let dict = property_dictionary(&[
        (P_AREA_NAME, "Area_Name", 13),
        (P_AREA_TERRITORY, "Area_Territory", 20),
        (P_AREA_REGION, "Area_Region", 20),
        (P_AREA_REGION_ID, "Area_RegionID", 15),
        (P_DUNGEON_NAME, "Dungeon_Name", 13),
        (P_DUNGEON_MAP, "Dungeon_MapData", 20),
        (P_DUNGEON_PARENT, "Dungeon_ParentDungeon", 20),
        (P_REGION_LIST, "Region_Map_List", 12),
        (P_REGION_ENTRY, "Region_Map_Entry", 11),
        (P_REGION_ID, "Region_ID", 15),
        (P_REGION_NAME, "Region_Name", 13),
    ]);
    // Classes: 10 area, 11 territory, 12 region, 13 dungeon, 14 region control, 15 other.
    let lib = LibraryBuilder::new(20)
        .define(10, &[])
        .define(11, &[(geo::TERRITORY_LIST_ATTR, ValueType::Reference)])
        .define(12, &[])
        .define(13, &[(geo::DUNGEON_POSITION_ATTR, ValueType::Reference)])
        .define(14, &[(geo::REGION_TABLE_ATTR, ValueType::Reference)])
        .define(15, &[])
        .build();
    let mut pos = Vec::new();
    put_position(&mut pos, 2, (100, 50), 0, [10.0, 20.0, 30.0]);
    let mut table = Vec::new();
    put_tsize(&mut table, 0, 1);
    table.extend(le(&[3, 2]));
    let entry = {
        let mut s = Vec::new();
        put_tsize(&mut s, 0, 2);
        s.extend(le(&[P_REGION_ID, P_REGION_ID, 3]));
        s.extend(le(&[P_REGION_NAME, P_REGION_NAME]));
        s.extend(si("Northreach"));
        s
    };
    let mut list = le(&[1, P_REGION_ENTRY]);
    list.extend(entry);
    let rec = |did: u32, b: RecordBuilder| (did, b.build());
    let records = [
        rec(
            AREA,
            RecordBuilder::new(AREA, 10)
                .class(10, &[])
                .script(0, 10, &[]),
        ),
        rec(
            TERRITORY,
            RecordBuilder::new(TERRITORY, 11)
                .class(11, &[(geo::TERRITORY_LIST_ATTR, ValueType::Reference)])
                .script(0, 11, &[Value::Ref(Ref(1))])
                .object(1, 25, &le(&[0])),
        ),
        rec(
            REGION,
            RecordBuilder::new(REGION, 12)
                .class(12, &[])
                .script(0, 12, &[]),
        ),
        rec(
            DUNGEON,
            RecordBuilder::new(DUNGEON, 13)
                .class(13, &[(geo::DUNGEON_POSITION_ATTR, ValueType::Reference)])
                .script(0, 13, &[Value::Ref(Ref(1))])
                .object(1, 160, &pos),
        ),
        rec(
            SUB_DUNGEON,
            RecordBuilder::new(SUB_DUNGEON, 13)
                .class(13, &[(geo::DUNGEON_POSITION_ATTR, ValueType::Reference)])
                .script(0, 13, &[Value::Ref(Ref::NULL)]),
        ),
        rec(
            CONTROL,
            RecordBuilder::new(CONTROL, 14)
                .class(14, &[(geo::REGION_TABLE_ATTR, ValueType::Reference)])
                .script(0, 14, &[Value::Ref(Ref(1))])
                .object(1, 35, &table)
                .object(2, 199, &si("Northreach")),
        ),
        rec(
            OTHER,
            RecordBuilder::new(OTHER, 15)
                .class(15, &[])
                .script(0, 15, &[]),
        ),
    ];
    let mut src = MemorySource::new()
        .with(0x3400_0000, dict)
        .with(0x5600_0000, lib)
        .with(
            0x2800_0000,
            did_map(0x2800_0000, &[(0xA, 0x2800_000E, "WEENIECONTENT")]),
        )
        .with(
            0x2800_000E,
            did_map(0x2800_000E, &[(1, CONTROL, "RegionControl")]),
        );
    for (did, bytes) in records {
        src.insert(did, bytes);
    }
    let set = |did: u32, entries: &[(u32, Vec<u8>)]| {
        (
            did + 0x0900_0000,
            property_set_record(did + 0x0900_0000, entries),
        )
    };
    for (did, bytes) in [
        set(
            AREA,
            &[
                (P_AREA_NAME, si("Ashvale")),
                (P_AREA_TERRITORY, le(&[TERRITORY])),
            ],
        ),
        set(
            TERRITORY,
            &[
                (P_AREA_NAME, si("Eastmarch")),
                (P_AREA_REGION, le(&[REGION])),
            ],
        ),
        set(
            REGION,
            &[
                (P_AREA_NAME, si("Northreach")),
                (P_AREA_REGION_ID, le(&[3])),
            ],
        ),
        set(
            DUNGEON,
            &[
                (P_DUNGEON_NAME, si("Deepholt")),
                (P_DUNGEON_MAP, le(&[0x7800_0001])),
                (P_DUNGEON_PARENT, le(&[0])),
            ],
        ),
        set(
            SUB_DUNGEON,
            &[
                (P_DUNGEON_NAME, si("Lower  DEEPHOLT")),
                (P_DUNGEON_PARENT, le(&[DUNGEON])),
            ],
        ),
        set(CONTROL, &[(P_REGION_LIST, list.clone())]),
        set(OTHER, &[]),
    ] {
        src.insert(did, bytes);
    }
    src
}

#[test]
fn store_loads_library_states_and_objects() {
    let store = ObjectStore::new(synthetic_world());
    assert_eq!(store.library_did(), LIBRARY_DID);
    let lib = store.library().expect("library");
    assert_eq!(lib.defined_count(), 6);
    let h = store
        .header(Did(DUNGEON))
        .expect("header")
        .expect("present");
    assert_eq!(h.root_class, 13);
    let a = store.state(Did(DUNGEON)).expect("state").expect("present");
    let b = store.state(Did(DUNGEON)).expect("state").expect("present");
    assert!(Arc::ptr_eq(&a, &b), "cached");
    assert_eq!(store.cached(), 1);
    store.clear_cache();
    assert_eq!(store.cached(), 0);
    assert!(store.state(Did(0x7000_9999)).expect("absent").is_none());
    assert!(matches!(
        store.state(Did(0x2500_0000)),
        Err(WStateError::NotObjectDid { .. })
    ));
    let obj = store.object(Did(AREA)).expect("object").expect("present");
    assert_eq!(obj.class, 10);
    assert_eq!(obj.properties.map(|p| p.len()), Some(2));
    assert_eq!(
        store.weenie("RegionControl").expect("weenie"),
        Some(Did(CONTROL))
    );
    assert!(matches!(
        store.follow_did(Did(0x7000_7777)),
        Err(WStateError::Missing { .. })
    ));
    assert!(store.singleton(3).expect("singleton").is_none());
}

#[test]
fn store_reports_missing_library() {
    let store =
        ObjectStore::new(MemorySource::new().with(AREA, RecordBuilder::new(AREA, 1).build()));
    assert!(matches!(store.library(), Err(WStateError::Missing { .. })));
    assert!(store.state(Did(AREA)).is_err());
    let header = store
        .header(Did(AREA))
        .expect("header works without a library");
    assert_eq!(header.map(|h| h.root_class), Some(1));
}

#[test]
fn geo_resolves_chain_dungeons_and_regions() {
    let store = ObjectStore::new(synthetic_world());
    let strings = tessera_text::Strings::new(tessera_text::MemorySource::new());
    let geo = Geo::new(&store).expect("geo");
    assert_eq!(geo.kind(Did(AREA)).expect("kind"), Some(GeoKind::Area));
    assert_eq!(geo.kind(Did(OTHER)).expect("kind"), None);
    let chain = geo.area_chain(Did(AREA)).expect("chain");
    assert_eq!(
        chain.territory.as_ref().map(|t| t.did),
        Some(Did(TERRITORY))
    );
    assert_eq!(chain.region.as_ref().and_then(|r| r.region_id), Some(3));
    let names: Vec<_> = [
        chain.area.name.as_ref(),
        chain.territory.as_ref().and_then(|t| t.name.as_ref()),
        chain.region.as_ref().and_then(|r| r.name.as_ref()),
    ]
    .into_iter()
    .map(|n| n.and_then(|n| render_name(&strings, n)))
    .collect();
    assert_eq!(
        names,
        vec![
            Some("Ashvale".into()),
            Some("Eastmarch".into()),
            Some("Northreach".into())
        ]
    );
    assert!(matches!(
        geo.area(Did(TERRITORY)),
        Err(WStateError::WrongKind { .. })
    ));
    assert!(matches!(
        geo.area(Did(0x7000_5555)),
        Err(WStateError::Missing { .. })
    ));

    let d = geo.dungeon(Did(DUNGEON)).expect("dungeon");
    assert_eq!(d.map_data, Some(Did(0x7800_0001)));
    assert_eq!(d.parent, None);
    let p = d.position.expect("position");
    assert_eq!(p.region(), Some(2));
    assert_eq!(p.landblock(), Some((100, 50)));
    let sub = geo.dungeon(Did(SUB_DUNGEON)).expect("sub dungeon");
    assert_eq!(sub.parent, Some(Did(DUNGEON)));
    assert!(sub.position.is_none());

    let a = geo.region_table().expect("table");
    let b = geo.region_table_from_state().expect("table from state");
    assert_eq!(a, b);
    assert_eq!(a.len(), 1);
    assert_eq!(a[0].number, 3);

    let dids = [
        AREA,
        TERRITORY,
        REGION,
        DUNGEON,
        SUB_DUNGEON,
        CONTROL,
        OTHER,
        0x7000_0099,
    ]
    .map(Did);
    let (index, report) = GeoIndex::build(&geo, Some(&strings), dids);
    assert_eq!(report.scanned, 8);
    assert_eq!(report.absent, 1);
    assert_eq!(report.failed, 0);
    assert_eq!(report.mismatched, 0);
    assert_eq!(report.named, 5);
    assert_eq!(index.len(), 6);
    assert_eq!(index.classes(GeoKind::Dungeon), &[13]);
    assert_eq!(index.find("ashvale")[0].did, Did(AREA));
    assert_eq!(index.find("  ASHVALE ").len(), 1);
    assert_eq!(index.find_kind("Northreach", GeoKind::Region).len(), 1);
    assert_eq!(index.find_kind("Northreach", GeoKind::Area).len(), 0);
    assert_eq!(index.find("lower deepholt")[0].did, Did(SUB_DUNGEON));
    assert_eq!(index.search("deepholt").count(), 2);
    assert_eq!(index.name(Did(TERRITORY)), Some("Eastmarch"));
    assert_eq!(
        index.area_names(Did(AREA)),
        [Some("Ashvale"), Some("Eastmarch"), Some("Northreach")]
    );
    assert_eq!(index.get(Did(REGION)).and_then(|e| e.region_id), Some(3));
    assert!(index.get(Did(OTHER)).is_none());
    // Re-inserting an entry replaces it and its name.
    let mut index = index;
    let mut e = index.get(Did(AREA)).cloned().expect("area");
    e.name = Some("Ashfold".into());
    index.insert(e);
    assert!(index.find("ashvale").is_empty());
    assert_eq!(index.find("ashfold").len(), 1);
    assert_eq!(index.len(), 6);
}

#[test]
fn value_type_codes() {
    for code in [1, 2, 3, 130, 131, 195] {
        let t = ValueType::from_code(code).expect("known");
        assert_eq!(t.code(), code);
        assert_eq!(t.size(), if code & 0x80 != 0 { 8 } else { 4 });
    }
    assert!(ValueType::from_code(4).is_none());
    assert!(has_codec(225));
    assert!(!has_codec(3053));
    assert_eq!(codec_name(160), Some("position"));
    assert!(is_object_did(0x7600_0001u32));
    assert!(!is_object_did(0x7800_0001u32));
}

// --- regression tests for review findings ---------------------------------------------

/// A scene-info body with `n` entries whose text is a literal StringInfo.
fn scene_body_literal(n: u32, text: &str) -> Vec<u8> {
    let mut body = Vec::new();
    put_string_info_literal(&mut body, "");
    body.extend(le(&[0x7000_0ABC, n]));
    for i in 0..n {
        body.extend(le(&[SCENE_SENTINEL, i + 1]));
        body.extend([0f32, 1.0].iter().flat_map(|f| f.to_le_bytes()));
        body.extend(le(&[2]));
        put_string_info_literal(&mut body, text);
        body.extend(le(&[3, 4]));
        body.push(1);
    }
    body
}

#[test]
fn scene_info_accepts_short_literal_texts() {
    // The smallest entry has a 5-byte literal StringInfo (34 bytes in all), so entries
    // with literal texts of up to 3 UTF-16 units must not fail the bounds pre-check.
    for text in ["", "a", "abc", "abcd"] {
        for n in [1, 6] {
            let body = scene_body_literal(n, text);
            let Native::SceneInfo(s) = native(427, &body) else {
                panic!("scene info");
            };
            assert_eq!(s.entries.len(), n as usize, "{text:?} × {n}");
            assert!(s.entries.iter().all(|e| e.flag));
        }
    }
    // A count one larger than the entries present still fails without allocating.
    let mut body = scene_body_literal(2, "");
    let at = body.len() - 2 * 34 - 4;
    body[at..at + 4].copy_from_slice(&3u32.to_le_bytes());
    let b = RecordBuilder {
        items: vec![example_builder().items[0].clone()],
        ..example_builder()
    }
    .object(1, 427, &body);
    assert!(ObjectState::parse(&b.build(), Did(0x7000_0ABC), DecodeContext::bare()).is_err());
}

#[test]
fn testkit_position_flags_follow_the_writer_rule() {
    for (region, cell, flags) in [
        (1u8, 0u16, 0xDBu8),
        (1, 7, 0x5B),
        (2, 0, 0x9B),
        (2, 7, 0x1B),
    ] {
        let mut b = Vec::new();
        put_position(&mut b, region, (3, 4), cell, [1.0, 2.0, 3.0]);
        assert_eq!(b[0], flags, "region {region} cell {cell}");
        let Native::Position(p) = native(160, &b) else {
            panic!("position");
        };
        assert_eq!(p.region(), Some(region));
        assert_eq!(p.landblock(), Some((3, 4)));
    }
}

