#[test]
fn quest_targets_keep_their_tsize_headers() {
    let mut body = Vec::new();
    put_tsize(&mut body, 3, 0);
    body.extend(le(&[2]));
    put_tsize(&mut body, 1, 0);
    put_tsize(&mut body, 2, 0);
    put_tsize(&mut body, 4, 0);
    put_tsize(&mut body, 5, 1);
    body.extend(le(&[0x7000_0003]));
    put_tsize(&mut body, 6, 0);
    let Native::QuestTargets(q) = native(2479, &body) else {
        panic!("quest targets");
    };
    let hints = |s: &[tessera_formats::TSize]| s.iter().map(|t| t.hint).collect::<Vec<_>>();
    assert_eq!(q.sizes.locations.hint, 3);
    assert_eq!(hints(&q.sizes.tables), vec![1, 2]);
    assert_eq!(q.sizes.layered.hint, 4);
    assert_eq!((q.sizes.quests.hint, q.sizes.quests.count), (5, 1));
    assert_eq!(hints(&q.sizes.objectives), vec![6]);
    assert_eq!(q.quests.len(), 1);
}

