#[test]
fn header_with_imports_skips_the_bundle() {
    let mut b = example_builder()
        .import(0x4E, 0x7000_0001, 16)
        .import(0x45, 0x7000_0002, 0);
    // A bundle that does not decode does not matter for the header read.
    b.bundle_tail = vec![0xFF; 3];
    let bytes = b.build();
    let (h, size, imports) = ObjectHeader::parse_with_imports(&bytes).expect("imports");
    assert_eq!(
        (h.did, h.root_class),
        (Did(0x7000_0ABC), u32::from(EX_CLASS))
    );
    assert_eq!(size.count, 2);
    assert_eq!(imports.len(), 2);
    assert_eq!(imports[0].did, Did(0x7000_0001));
    assert_eq!(imports[0].flags, Import::FLAG_DID_ITEM);
    // Truncated import lists fail; a hostile count fails without allocating.
    for n in 8..bytes.len().min(8 + 1 + 18) {
        assert!(
            ObjectHeader::parse_with_imports(&bytes[..n]).is_err(),
            "prefix {n}"
        );
    }
    let mut hostile = bytes[..8].to_vec();
    put_tsize(&mut hostile, 2, 0x3FFF_FFFF);
    assert!(ObjectHeader::parse_with_imports(&hostile).is_err());

    let src = MemorySource::new().with(0x7000_0ABC, bytes);
    let store = ObjectStore::new(src);
    let (h, imports) = store
        .imports(Did(0x7000_0ABC))
        .expect("imports")
        .expect("present");
    assert_eq!(h.root_class, u32::from(EX_CLASS));
    assert_eq!(imports.len(), 2);
    assert!(store.imports(Did(0x7000_0ABD)).expect("absent").is_none());
}

#[test]
fn library_l8_check_is_linear_on_deep_chains() {
    // `leaves` listed classes hang off the bottom of a chain of `chain` undefined classes,
    // under one listed root. A per-class walk up the chain would take leaves × chain steps.
    // Defined classes need 16-bit indices, so the leaves come first: root 0, leaves
    // 1..=leaves, then the chain.
    let (chain, leaves) = (200_000usize, 10_000usize);
    let n = 1 + leaves + chain;
    let mut b = LibraryBuilder::new(n).define(0, &[(H_INT, ValueType::Int)]);
    let first = 1 + leaves;
    b.parents[first] = 0;
    for i in first + 1..n {
        b.parents[i] = u32::try_from(i - 1).expect("index");
    }
    let bottom = u32::try_from(n - 1).expect("index");
    for k in 0..leaves {
        let i = 1 + k;
        // Every other leaf drops the root's attribute (an L8 warning).
        b = if k % 2 == 0 {
            b.define(i, &[(H_INT, ValueType::Int), (H_REF, ValueType::Reference)])
        } else {
            b.define(i, &[(H_REF, ValueType::Reference)])
        }
        .parent(i, bottom);
    }
    let bytes = b.build();
    let t = std::time::Instant::now();
    let lib = ClassLibrary::parse(&bytes).expect("parse");
    let elapsed = t.elapsed();
    assert!(
        elapsed < std::time::Duration::from_secs(3),
        "parse took {elapsed:?}"
    );
    let not_flat = lib
        .warnings()
        .iter()
        .filter(|w| matches!(w, LibraryWarning::NotFlattened { ancestor: 0, .. }))
        .count();
    assert_eq!(not_flat, library::MAX_LIBRARY_WARNINGS.min(leaves / 2));
    let leaf = 1u32;
    assert_eq!(lib.depth(leaf), chain + 1);
    assert_eq!(lib.depth(0), 0);
    assert!(lib.is_a(leaf, 0));
    assert!(lib.is_a(leaf, bottom));
    assert!(lib.is_a(leaf, leaf));
    assert!(!lib.is_a(0, leaf));
    assert!(!lib.is_a(leaf, leaf + 1));
    assert!(!lib.is_a(0, bottom));
    assert!(!lib.is_a(leaf, u32::MAX));
    assert_eq!(lib.depth(u32::MAX), 0);
    // Repeated queries are cheap: depth is precomputed and is_a on unrelated leaves of
    // equal depth does not walk.
    let t = std::time::Instant::now();
    for k in 0..leaves {
        let c = leaf + u32::try_from(k).expect("index");
        assert_eq!(lib.depth(c), chain + 1);
        assert!(!lib.is_a(c, leaf + 1) || c == leaf + 1);
    }
    assert!(t.elapsed() < std::time::Duration::from_secs(5));
}

#[test]
fn library_l8_finds_nearest_listed_ancestor_through_undefined_classes() {
    // 1 (listed) <- 2 (undefined) <- 3 (listed, flattened) <- 4 (undefined) <- 5 (listed,
    // missing 3's own attribute).
    let mut b = LibraryBuilder::new(6)
        .define(1, &[(H_INT, ValueType::Int)])
        .define(3, &[(H_INT, ValueType::Int), (H_REF, ValueType::Reference)])
        .define(5, &[(H_INT, ValueType::Int)])
        .parent(3, 2)
        .parent(5, 4);
    b.parents[2] = 1;
    b.parents[4] = 3;
    let lib = ClassLibrary::parse(&b.build()).expect("parse");
    let flat: Vec<_> = lib
        .warnings()
        .iter()
        .filter(|w| matches!(w, LibraryWarning::NotFlattened { .. }))
        .collect();
    assert_eq!(
        flat,
        vec![&LibraryWarning::NotFlattened {
            class: 5,
            ancestor: 3
        }]
    );
    assert_eq!(lib.depth(5), 4);
    assert_eq!(lib.ancestors(5).collect::<Vec<_>>(), vec![4, 3, 2, 1]);
}

#[test]
fn store_cache_is_lru_bounded_by_count_and_bytes() {
    let dids = [AREA, TERRITORY, REGION, DUNGEON].map(Did);
    let store = ObjectStore::new(synthetic_world()).with_cache_limits(CacheLimits {
        records: 2,
        ..CacheLimits::default()
    });
    let state = |d: Did| store.state(d).expect("state").expect("present");
    let a = state(dids[0]);
    state(dids[1]);
    assert!(Arc::ptr_eq(&a, &state(dids[0])), "hit refreshes A");
    state(dids[2]); // evicts the least recently used: B
    assert!(store.is_cached(dids[0]));
    assert!(!store.is_cached(dids[1]));
    assert!(store.is_cached(dids[2]));
    // New records keep being cached once the cache is full.
    state(dids[3]);
    assert!(store.is_cached(dids[3]));
    assert_eq!(store.cached(), 2);
    assert!(store.cached_bytes() > 0);
    // Explicit eviction (landblock unload).
    assert_eq!(store.evict([dids[3], dids[1]]), 1);
    assert_eq!(store.cached(), 1);

    // A byte budget that holds one record at a time.
    let one = store.cached_bytes();
    store.set_cache_limits(CacheLimits {
        records: 100,
        bytes: one + one / 2,
        max_payload: MAX_CACHED_PAYLOAD,
    });
    for d in dids {
        state(d);
        assert!(store.is_cached(d));
        assert!(store.cached_bytes() <= one + one / 2);
    }
    assert!(store.cached() < dids.len());

    // Disabled cache: decodes still work, nothing is kept.
    store.set_cache_limits(CacheLimits {
        records: 0,
        ..CacheLimits::default()
    });
    assert_eq!(store.cached(), 0);
    state(dids[0]);
    assert_eq!(store.cached(), 0);
    assert_eq!(store.cache_limits().records, 0);
    // Payloads over max_payload are never cached.
    store.set_cache_limits(CacheLimits {
        max_payload: 4,
        ..CacheLimits::default()
    });
    state(dids[0]);
    assert_eq!(store.cached(), 0);
}

const AREA_BAD_SET: u32 = 0x7000_0001;
const AREA_NO_SET: u32 = 0x7000_0002;
const AREA_ODD: u32 = 0x7000_0003;

/// The synthetic world plus area-class records that do not classify: one whose property
/// set does not decode, one without a property set, one whose set lacks the area
/// properties; and five more records of the "other" class.
fn awkward_world() -> MemorySource {
    let mut src = synthetic_world();
    for did in [AREA_BAD_SET, AREA_NO_SET, AREA_ODD] {
        src.insert(
            did,
            RecordBuilder::new(did, 10)
                .class(10, &[])
                .script(0, 10, &[])
                .build(),
        );
    }
    let mut bad = (AREA_BAD_SET + 0x0900_0000).to_le_bytes().to_vec();
    bad.extend([0, 5, 0xFF, 0xFF]);
    src.insert(AREA_BAD_SET + 0x0900_0000, bad);
    src.insert(
        AREA_ODD + 0x0900_0000,
        property_set_record(AREA_ODD + 0x0900_0000, &[(P_AREA_NAME, si("Odd"))]),
    );
    for k in 1..=5 {
        let did = OTHER + k;
        src.insert(
            did,
            RecordBuilder::new(did, 15)
                .class(15, &[])
                .script(0, 15, &[])
                .build(),
        );
        src.insert(
            did + 0x0900_0000,
            property_set_record(did + 0x0900_0000, &[]),
        );
    }
    src
}

#[test]
fn geo_index_survives_bad_first_records_of_a_class() {
    let store = ObjectStore::new(awkward_world());
    let strings = tessera_text::Strings::new(tessera_text::MemorySource::new());
    let geo = Geo::new(&store).expect("geo");
    let mut dids = vec![AREA_BAD_SET, AREA_NO_SET, AREA_ODD, AREA, TERRITORY, REGION];
    dids.extend((0..=5).map(|k| OTHER + k));
    let (index, report) = GeoIndex::build(&geo, Some(&strings), dids.iter().map(|&d| Did(d)));
    assert_eq!(report.failed, 1, "{report:?}");
    assert_eq!(report.no_properties, 1, "{report:?}");
    assert!(index.get(Did(AREA)).is_some(), "area indexed: {report:?}");
    assert_eq!(index.classes(GeoKind::Area), &[10]);
    assert_eq!(index.of_kind(GeoKind::Area).count(), 1);
    assert!(index.get(Did(AREA_ODD)).is_none());
    // Six "other" records: NEGATIVE_PROBES probed, the rest skipped.
    assert_eq!(report.classes_other, 1);
    assert_eq!(report.skipped, 6 - usize::from(geo::NEGATIVE_PROBES));
    assert_eq!(report.mismatched, 0);
    assert_eq!(
        report.scanned,
        report.absent
            + report.failed
            + report.no_properties
            + report.skipped
            + report.properties_read
    );

    // The incremental builder gives the same result in chunks.
    let mut b = GeoIndexBuilder::new();
    for chunk in dids.chunks(4) {
        b.scan_all(&geo, Some(&strings), chunk.iter().map(|&d| Did(d)));
    }
    assert_eq!(b.report().scanned, dids.len());
    let (index2, report2) = b.finish();
    assert_eq!(report2, report);
    assert_eq!(index2.len(), index.len());

    // Once a class is known to be geographic, a record that does not classify counts.
    let (_, report) = GeoIndex::build(&geo, Some(&strings), [AREA, AREA_ODD].map(Did));
    assert_eq!(report.mismatched, 1);
}

#[test]
fn dungeon_position_distinguishes_null_from_missing_attribute() {
    const NOT_POS: u32 = 0x7000_0022;
    let mut src = synthetic_world();
    src.insert(
        NOT_POS,
        RecordBuilder::new(NOT_POS, 13)
            .class(13, &[(geo::DUNGEON_POSITION_ATTR, ValueType::Reference)])
            .script(0, 13, &[Value::Ref(Ref(1))])
            .object(1, 199, &si("x"))
            .build(),
    );
    let store = ObjectStore::new(src);
    let geo = Geo::new(&store).expect("geo");
    assert!(geo.dungeon_position(Did(DUNGEON)).expect("ok").is_some());
    assert!(
        geo.dungeon_position(Did(SUB_DUNGEON))
            .expect("null")
            .is_none()
    );
    assert!(
        geo.dungeon_position(Did(0x7000_0999))
            .expect("absent")
            .is_none()
    );
    for did in [OTHER, NOT_POS] {
        assert!(
            matches!(
                geo.dungeon_position(Did(did)),
                Err(WStateError::BadAttribute {
                    hash: geo::DUNGEON_POSITION_ATTR,
                    ..
                })
            ),
            "{did:#x}"
        );
    }
}

#[test]
fn area_names_checks_kinds() {
    let store = ObjectStore::new(synthetic_world());
    let strings = tessera_text::Strings::new(tessera_text::MemorySource::new());
    let geo = Geo::new(&store).expect("geo");
    let dids = [AREA, TERRITORY, REGION, DUNGEON, SUB_DUNGEON].map(Did);
    let (index, _) = GeoIndex::build(&geo, Some(&strings), dids);
    assert_eq!(
        index.area_names(Did(AREA)),
        [Some("Ashvale"), Some("Eastmarch"), Some("Northreach")]
    );
    for did in [TERRITORY, REGION, SUB_DUNGEON, 0x7000_0999] {
        assert_eq!(index.area_names(Did(did)), [None, None, None], "{did:#x}");
    }
    // An area whose territory slot names a dungeon ends the chain there.
    let mut index = index;
    let mut e = index.get(Did(AREA)).cloned().expect("area");
    e.parent = Some(Did(DUNGEON));
    index.insert(e);
    assert_eq!(index.area_names(Did(AREA)), [Some("Ashvale"), None, None]);
}
